(function () {
  var ev = $input.all();
  var count = function (name, f) { return ev.filter(function (e) { return e.event === name && (!f || f(e)); }).length; };
  var rate = function (a, b) { return b > 0 ? Math.round((a / b) * 1000) / 10 : ""; };
  var sentFirst = count("sent", function (e) { return e.step === "first_touch"; });
  var replies = count("reply_interested") + count("reply_objection") + count("reply_not_now") + count("reply_stop");
  var positive = count("reply_interested") + count("reply_objection");
  var by = {};
  ev.forEach(function (e) {
    if (e.event !== "sent") return;
    var k = (e.channel || "?") + "/" + (e.line || "?");
    by[k] = by[k] || { sent: 0 };
    by[k].sent++;
  });
  return [{
    sourced: count("sourced"), scored_qualify: count("scored", function (e) { return e.tier === "qualify"; }),
    drafted: count("drafted"), approved: count("approved"), rejected_by_human: count("rejected"), sent: count("sent"),
    first_touch_sent: sentFirst, replies: replies, replies_interested: count("reply_interested"),
    replies_objection: count("reply_objection"), replies_not_now: count("reply_not_now"), stops: count("reply_stop"),
    applications: count("applied"), spec_calls: count("spec_call"), specs_signed: count("spec_signed"),
    builds_delivered: count("build_delivered"), builds_passed: count("build_passed"), converted: count("converted"),
    reply_rate_pct: rate(replies, sentFirst), positive_reply_rate_pct: rate(positive, sentFirst), stop_rate_pct: rate(count("reply_stop"), sentFirst),
    application_rate_pct: rate(count("applied"), sentFirst), spec_signed_per_call_pct: rate(count("spec_signed"), count("spec_call")),
    pass_rate_pct: rate(count("build_passed"), count("build_delivered")), pass_to_convert_pct: rate(count("converted"), count("build_passed")),
    sent_by_channel_line: JSON.stringify(by)
  }];
})()
